# Deterministic ROM generation from the installed Microsoft YaHei font.
# Generated files are ordinary synthesizable ROM initialization assets.
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$uiDir=Join-Path (Split-Path -Parent $PSScriptRoot) 'src\ui'
$entries=Get-Content -LiteralPath (Join-Path $uiDir 'ui_strings.json') -Raw | ConvertFrom-Json
$glyphs=[System.Collections.Generic.List[char]]::new()
foreach($ch in ' 0123456789-ABCDEF'.ToCharArray()){$glyphs.Add($ch)}
foreach($entry in $entries.PSObject.Properties){
    if($entry.Value.Length -gt 32){throw "String too long: $($entry.Name)"}
    foreach($ch in $entry.Value.ToCharArray()){if(-not $glyphs.Contains($ch)){$glyphs.Add($ch)}}
}
if($glyphs.Count -gt 256){throw 'Glyph address overflow'}
$defines=[System.Collections.Generic.List[string]]::new()
$defines.Add('// Generated by sim/generate_ui_font.ps1; do not edit.')
$defines.Add(('`define UI_G_DIGIT0 8''d1'))
$defines.Add(('`define UI_G_DASH 8''d11'))
$strings=[string[]]::new(2048)
for($i=0;$i -lt $strings.Length;$i++){$strings[$i]='000'}
$stringId=1
foreach($entry in $entries.PSObject.Properties){
    $defines.Add(('`define UI_S_{0} 6''d{1}' -f $entry.Name,$stringId))
    $cell=0
    foreach($ch in $entry.Value.ToCharArray()){
        $glyph=$glyphs.IndexOf($ch)
        $half=([int]$ch -ge 32 -and [int]$ch -le 126)
        if($cell -ge 32){throw "Half-cell layout overflow: $($entry.Name)"}
        $strings[$stringId*32+$cell]=('{0:X3}' -f $glyph);$cell++
        if(-not $half){
            if($cell -ge 32){throw "Half-cell layout overflow: $($entry.Name)"}
            $strings[$stringId*32+$cell]=('{0:X3}' -f (256+$glyph));$cell++
        }
    }
    $stringId++
}
if($stringId -gt 64){throw 'String address overflow'}
$rows=[string[]]::new(4096)
for($i=0;$i -lt $rows.Length;$i++){$rows[$i]='00000000'}
$bitmap=[System.Drawing.Bitmap]::new(16,16)
$graphics=[System.Drawing.Graphics]::FromImage($bitmap)
$graphics.TextRenderingHint=[System.Drawing.Text.TextRenderingHint]::SingleBitPerPixelGridFit
$font=[System.Drawing.Font]::new('Microsoft YaHei',13,[System.Drawing.FontStyle]::Regular,[System.Drawing.GraphicsUnit]::Pixel)
$latinFont=[System.Drawing.Font]::new('Consolas',13,[System.Drawing.FontStyle]::Regular,[System.Drawing.GraphicsUnit]::Pixel)
$format=[System.Drawing.StringFormat]::GenericTypographic.Clone()
$format.FormatFlags=$format.FormatFlags -bor [System.Drawing.StringFormatFlags]::NoWrap
for($g=1;$g -lt $glyphs.Count;$g++){
    $graphics.Clear([System.Drawing.Color]::Black)
    $drawFont=if([int]$glyphs[$g] -ge 32 -and [int]$glyphs[$g] -le 126){$latinFont}else{$font}
    $graphics.DrawString([string]$glyphs[$g],$drawFont,[System.Drawing.Brushes]::White,[single]0,[single]-1,$format)
    for($y=0;$y -lt 16;$y++){
        [uint32]$ink=0;[uint32]$outline=0
        for($x=0;$x -lt 16;$x++){
            if($bitmap.GetPixel($x,$y).R -gt 128){$ink=$ink -bor (1 -shl (15-$x))}
            $near=$false
            foreach($delta in @(@(0,0),@(1,0),@(-1,0),@(0,1),@(0,-1))){
                $xx=$x+$delta[0];$yy=$y+$delta[1]
                if($xx -ge 0 -and $xx -lt 16 -and $yy -ge 0 -and $yy -lt 16 -and $bitmap.GetPixel($xx,$yy).R -gt 128){$near=$true}
            }
            if($near){$outline=$outline -bor (1 -shl (15-$x))}
        }
        $rows[$g*16+$y]=('{0:X4}{1:X4}' -f $ink,$outline)
    }
}
$graphics.Dispose();$bitmap.Dispose();$font.Dispose();$latinFont.Dispose();$format.Dispose()
[System.IO.File]::WriteAllLines((Join-Path $uiDir 'ui_font16.mem'),$rows,[System.Text.Encoding]::ASCII)
[System.IO.File]::WriteAllLines((Join-Path $uiDir 'ui_strings.mem'),$strings,[System.Text.Encoding]::ASCII)
[System.IO.File]::WriteAllLines((Join-Path $uiDir 'ui_assets.vh'),$defines,[System.Text.Encoding]::ASCII)
Write-Host "Generated $($glyphs.Count) glyphs and $($stringId-1) strings."
